package message

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/message/db"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql; it holds no message and no
// recipient of its own, so two of these serve one queue.
type PostgresStore struct {
	q *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{q: db.New(pool)}
}

// Enqueue stores the message, or returns the one the sender already
// stored under the same key.
func (s *PostgresStore) Enqueue(ctx context.Context, m *Message) (*Message, error) {
	row, err := s.q.EnqueueMessage(ctx, db.EnqueueMessageParams{
		ID:             string(m.id),
		RecipientGrn:   m.recipient.String(),
		SenderGrn:      m.sender.String(),
		IdempotencyKey: m.idempotencyKey,
		Body:           m.body,
		CreatedAt:      stamp(m.createdAt),
	})
	if err != nil {
		return nil, errorx.Wrap(err, "message store: enqueue")
	}
	return rowToMessage(row)
}

// Claim hands the recipient's oldest ready message to one reader and
// holds it for lease, or returns ErrNoMessageReady.
func (s *PostgresStore) Claim(ctx context.Context, recipient grn.GRN, lease time.Duration) (*Claim, error) {
	claimID, err := newClaimID()
	if err != nil {
		return nil, err
	}
	row, err := s.q.ClaimMessage(ctx, db.ClaimMessageParams{
		ClaimID:      text(string(claimID)),
		Lease:        interval(lease),
		RecipientGrn: recipient.String(),
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, ErrNoMessageReady
		}
		return nil, errorx.Wrap(err, "message store: claim")
	}
	return rowToClaim(row)
}

// Complete reports the claimed message delivered. A claim handed on to
// another reader matches no row, hence ErrStaleClaim.
func (s *PostgresStore) Complete(ctx context.Context, c *Claim) error {
	rows, err := s.q.CompleteMessage(ctx, db.CompleteMessageParams{
		ID:      string(c.message.id),
		ClaimID: text(string(c.id)),
	})
	if err != nil {
		return errorx.Wrap(err, "message store: complete")
	}
	if rows == 0 {
		return ErrStaleClaim
	}
	return nil
}

// rowToMessage converts a sqlc row into the domain aggregate. A stored
// value that no longer parses is data corruption, hence internal.
func rowToMessage(row db.Message) (*Message, error) {
	recipient, err := grn.Parse(row.RecipientGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "message store: recipient grn", errorx.KindInternal)
	}
	sender, err := grn.Parse(row.SenderGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "message store: sender grn", errorx.KindInternal)
	}
	return &Message{
		id:             ID(row.ID),
		recipient:      recipient,
		sender:         sender,
		idempotencyKey: row.IdempotencyKey,
		body:           row.Body,
		createdAt:      row.CreatedAt.Time,
	}, nil
}

// rowToClaim converts the row a claim just wrote. The claim columns are
// what that write set, so a row without them is data corruption.
func rowToClaim(row db.Message) (*Claim, error) {
	m, err := rowToMessage(row)
	if err != nil {
		return nil, err
	}
	if !row.ClaimID.Valid || !row.ClaimExpiresAt.Valid {
		return nil, errorx.New(errorx.KindInternal, "message store: claimed row carries no claim")
	}
	return &Claim{
		message:   m,
		id:        ClaimID(row.ClaimID.String),
		expiresAt: row.ClaimExpiresAt.Time,
	}, nil
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}

// text converts a string to a valid pgtype.Text.
func text(s string) pgtype.Text {
	return pgtype.Text{String: s, Valid: true}
}

// interval converts a lease to the width Postgres measures it in.
func interval(d time.Duration) pgtype.Interval {
	return pgtype.Interval{Microseconds: d.Microseconds(), Valid: true}
}
